<?php
require_once __DIR__ . '/config_medical.php';medical_require_login();if($_SERVER['REQUEST_METHOD']!=='POST'||!medical_verify_csrf(isset($_POST['csrf_token'])?$_POST['csrf_token']:'')){http_response_code(400);die('Bad Request');}$id=(int)$_POST['id'];$rating=(int)$_POST['rating'];$comment=trim(isset($_POST['comment'])?$_POST['comment']:'');$row=medical_get_request($id);$uid=(int)$_SESSION['user_id'];if(!$row||(int)$row['user_id']!==$uid||$row['status']!=='completed'||!in_array($rating,array(1,3,5),true)){http_response_code(403);die('ไม่สามารถบันทึกการประเมินได้');}$stmt=$conn->prepare("INSERT INTO medical_feedback(request_id,user_id,rating,comment) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE rating=VALUES(rating),comment=VALUES(comment),updated_at=CURRENT_TIMESTAMP");$stmt->bind_param('iiis',$id,$uid,$rating,$comment);$stmt->execute();$stmt->close();medical_log($id,'feedback',$row['status'],$row['status'],'ประเมินความพึงพอใจ '.$rating.' คะแนน');medical_flash('success','บันทึกการประเมินเรียบร้อยแล้ว');header('Location:detail.php?id='.$id);exit;
